package run.ikaros.password; import java.time.Instant; import java.util.UUID; import org.springframework.stereotype.Service; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; import run.ikaros.common.NotFoundException; @Service public class PasswordFolderService{private final PasswordVaultRepository vaults;private final PasswordFolderRepository folders;private final PasswordVaultItemRepository items;private final PasswordItemFolderRepository bindings;public PasswordFolderService(PasswordVaultRepository v,PasswordFolderRepository f,PasswordVaultItemRepository i,PasswordItemFolderRepository b){vaults=v;folders=f;items=i;bindings=b;}public Mono<PasswordFolderView> create(UUID a,UUID v,CreatePasswordFolderRequest q){return ownVault(a,v).flatMap(x->folders.save(new PasswordFolderEntity(null,v,a,q.parentId(),q.encryptedName(),Instant.now(),null))).map(this::view);}public Flux<PasswordFolderView> list(UUID a,UUID v){return ownVault(a,v).flatMapMany(x->folders.findAllByVaultIdAndOwnerIdOrderByCreatedAtAsc(v,a).map(this::view));}public Mono<PasswordFolderView> bind(UUID a,UUID itemId,BindPasswordFolderRequest q){return items.findById(itemId).filter(i->i.ownerId().equals(a)&&!i.tombstone()).switchIfEmpty(Mono.error(new NotFoundException("Vault Item 不存在或无权访问"))).flatMap(i->folders.findById(q.folderId()).filter(f->f.ownerId().equals(a)&&f.vaultId().equals(i.vaultId())).switchIfEmpty(Mono.error(new NotFoundException("Folder 不存在或不属于该 Vault"))).flatMap(f->bindings.findByItemIdAndOwnerId(itemId,a).flatMap(old->bindings.save(new PasswordItemFolderEntity(old.id(),itemId,q.folderId(),i.vaultId(),a,old.createdAt()))).switchIfEmpty(bindings.save(new PasswordItemFolderEntity(null,itemId,q.folderId(),i.vaultId(),a,Instant.now())))).thenReturn(new PasswordFolderView(q.folderId(),i.vaultId(),null,null,null)));}private Mono<PasswordVaultEntity> ownVault(UUID a,UUID id){return vaults.findById(id).filter(v->v.ownerId().equals(a)).switchIfEmpty(Mono.error(new NotFoundException("Password Vault 不存在或无权访问")));}private PasswordFolderView view(PasswordFolderEntity f){return new PasswordFolderView(f.id(),f.vaultId(),f.parentId(),f.encryptedName(),f.createdAt());}}
